const FAKE_ASSETS_By_ID = {
  // populated by `fakePage`/`fakeMiniCardAsset` calls
};
/**
 * Shaped to match the real MatrixAssetSchema.json (confirmed by inspecting
 * the installed @squiz/dxp-cli-next's compiled source -- see the spec's §8):
 * `name` (not `title`), `metadata` as a key-value map of string ARRAYS (not
 * flat values). The card image is resolved via the `content-cardImagePhoto`
 * Related Asset metadata field (a bare asset ID, confirmed via a real
 * Matrix screenshot) -- so `mockImage` registers a separate fake image
 * asset here and references its ID, exercising the same second-resolveUri
 * path `resolveCardImage()` uses in production, rather than a `thumbnail`
 * shortcut.
 */
function fakePage({ id, name, category, date, description, mockImage }) {
  let imagePhotoId = '';
  if (mockImage) {
    imagePhotoId = `${id}9`;
    FAKE_ASSETS_By_ID[imagePhotoId] = {
      id: imagePhotoId,
      type: 'image',
      name: `${name} photo`,
      url: `https://picsum.photos/id/${id}/640/480`,
      urls: [`https://picsum.photos/id/${id}/640/480`],
    };
  }
  const page = {
    id: String(id),
    type: 'pageStandard',
    name,
    url: `https://example.com/pages/${id}`,
    metadata: {
      Category: [category],
      Date: [date],
      'content-cardDescription': [description],
      ...(imagePhotoId ? { 'content-cardImagePhoto': [imagePhotoId] } : {}),
    },
    child_count: 0,
  };
  FAKE_ASSETS_By_ID[String(id)] = page;
  return page;
}

/** A "Mini Cards" asset -- icon comes from its own 'content-cardIcon' metadata field. */
function fakeMiniCardAsset({ id, name, icon, href }) {
  const asset = {
    id: String(id),
    type: 'dataRecord',
    name,
    url: href,
    metadata: { 'content-cardIcon': [icon] },
    child_count: 0,
  };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

/**
 * A "Homepage Cards" asset -- icon/title/description read from the same
 * metadata fields as the other two modes (content-cardIcon,
 * content-cardTitle falling back to name, content-cardDescription).
 */
function fakeHomepageCardAsset({ id, name, icon, description, href }) {
  const asset = {
    id: String(id),
    type: 'pageStandard',
    name,
    url: href,
    metadata: {
      'content-cardIcon': [icon],
      'content-cardDescription': [description],
    },
    child_count: 0,
  };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

/**
 * A "News Cards" asset -- title/description/image reuse the same fields as
 * Display Cards mode; date reads 'news-datePublished', a distinct field
 * from Display Cards' Date. The "News" tag is fixed/standard for every card
 * in this mode, not sourced from metadata -- see main.js's NEWS_TAG_LABEL
 * constant.
 */
function fakeNewsCardAsset({ id, name, date, description, href }) {
  const imagePhotoId = `${id}9`;
  FAKE_ASSETS_By_ID[imagePhotoId] = {
    id: imagePhotoId,
    type: 'image',
    name: `${name} photo`,
    url: `https://picsum.photos/id/${id}/640/480`,
    urls: [`https://picsum.photos/id/${id}/640/480`],
  };
  const asset = {
    id: String(id),
    type: 'pageStandard',
    name,
    url: href,
    metadata: {
      'content-cardDescription': [description],
      'content-cardImagePhoto': [imagePhotoId],
      'news-datePublished': [date],
    },
    child_count: 0,
  };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

