import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

const ARROW_RIGHT_SVG =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true" focusable="false"><path d="M3 8h10m0 0-4-4m4 4-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

/**
 * Fallback only -- real sites have a `content-cardButtonText` metadata
 * field for this (confirmed via the real Content - 04 Card support
 * metadata schema export), used when that field is blank. See card.spec.md
 * assumption 2.
 */
const ACTION_TEXT = "Find out more";

/**
 * Card mode "News Cards" -- the tag label is fixed/standard for every card
 * (not sourced from content-cardIcon/Category like Display Cards' own tag).
 * The section heading/button used to be fixed text too, but are now the
 * editable `layoutOptions.sectionHeading`/`viewAllButton` fields, available
 * to every card mode -- see card.spec.md assumption 20.
 */
const NEWS_TAG_LABEL = "News";

/**
 * News Cards mode only shows its 3 most recent cards -- explicit user
 * decision, revision 0.5.16, reversing the earlier "no cap, render every
 * selected asset" decision (see card.spec.md assumption 7). Applied after
 * sorting newest-first, so it's always the 3 most recent, not the first 3
 * in selection order.
 */
const NEWS_CARDS_MAX_ITEMS = 3;

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- confirmed
 * directly against a live Squiz DXP backend via dxp-inspector (see
 * card.spec.md assumption 4). Checking for the `data` key's presence, not
 * just truthiness, avoids misreading a legitimate `{ data: null }`
 * "not found" envelope as the raw asset itself.
 */
function unwrapResolved(result) {
  if (!result || typeof result !== "object") return null;
  if ("data" in result) return result.data ?? null;
  return result;
}

/**
 * Resolves one matrix-asset-uri via fns.resolveUri -- confirmed working
 * against a real, live Squiz DXP backend. Best effort: any failure (bad
 * URI, unresolvable asset, missing fns) yields null rather than throwing.
 */
async function resolveAsset(uri, fns) {
  if (!uri || typeof fns?.resolveUri !== "function") return null;
  try {
    const result = await fns.resolveUri(uri);
    return unwrapResolved(result);
  } catch {
    return null;
  }
}

/**
 * Extracts the domain segment from a matrix-asset://<domain>/<id> URI, so a
 * Related Asset metadata value (a bare numeric ID, confirmed via a real
 * Matrix screenshot showing "content-cardImagePhoto #1626148" next to the
 * selected image's own "#<id>") can be turned back into a resolvable URI
 * without hardcoding a domain -- reuses whichever domain the current page's
 * own selected asset URI already carries.
 */
function parseAssetUriDomain(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/\d+(?::.+)?$/.exec(
    String(uri ?? ""),
  );
  return match ? match[1] : null;
}

function parseAssetUriId(uri) {
  const match = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)(?::.+)?$/.exec(
    String(uri ?? ""),
  );
  return match ? match[1] : null;
}

/**
 * SquizLink resolves to a plain string (bare URL) or a { text, url, target }
 * object -- same shape/handling as `global-alert`'s own resolveLink(). Used
 * by `layoutOptions.viewAllButton`, which replaced News Cards' old
 * auto-derived-from-`info.ctx.url` "/news" href (see card.spec.md
 * assumption 15, now superseded by assumption 20) with an editor-supplied
 * asset-picker link, available to every card mode.
 */
function resolveLink(link) {
  if (!link) return null;
  if (typeof link === "string") return { url: link, text: link, target: "_self" };
  if (typeof link === "object" && link.url) {
    return { url: link.url, text: link.text || link.url, target: link.target || "_self" };
  }
  return null;
}

function targetAttrs(target) {
  return target && target !== "_self" ? ` target="${escHTML(target)}" rel="noopener noreferrer"` : "";
}

/**
 * CONTENT_API_URL -- a Matrix REST resource acting as an authenticated
 * Content API proxy, confirmed working via the `content-api-picker` debug
 * component and reused directly by `image-gallery`'s own `imageFolder`
 * field. Read from info.env at call time, not editor-configurable.
 */
const ROOT_ID_PARAM_NAME = "rootId";

/**
 * Resolves `parentAsset`'s children into matrix-asset-uri strings, via a
 * plain unauthenticated fetch() against CONTENT_API_URL -- not info.fns,
 * which has no children-listing capability at all on this tenant. Only each
 * child's `id` is used to rebuild a matrix-asset-uri (reusing parentAsset's
 * own domain); the listing's own metadata is deliberately not relied on, so
 * every child still resolves through the exact same fns.resolveUri() +
 * per-mode mapping path as an individually-picked asset, keeping metadata
 * field handling identical either way. See card.spec.md assumption 8.
 */
async function resolveParentChildUris(parentAsset, contentApiUrl) {
  const domain = parseAssetUriDomain(parentAsset);
  const parentId = parseAssetUriId(parentAsset);
  if (!domain || !parentId || !contentApiUrl) return [];

  const url = `${contentApiUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(parentId)}`;

  let body;
  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    body = await res.json();
  } catch {
    return [];
  }

  if (!Array.isArray(body)) return [];
  return body
    .map((item) => item?.id)
    .filter(Boolean)
    .map((id) => `matrix-asset://${domain}/${id}`);
}

/**
 * Resolves the `content-cardImagePhoto` Related Asset metadata field (the
 * asset ID it stores, confirmed via a real Matrix screenshot) into a
 * {url, alt, width, height} image object, via a second fns.resolveUri call
 * -- falls back to the generic `thumbnail` attribute if that metadata
 * field is empty or fails to resolve. See card.spec.md assumption 2.
 */
async function resolveCardImage(page, domain, fns) {
  const imageRef = firstMetadataValue(
    page.metadata || {},
    "content-cardImagePhoto",
  );
  if (imageRef) {
    const imageUri = /^matrix-asset:\/\//.test(imageRef)
      ? imageRef
      : domain
        ? `matrix-asset://${domain}/${imageRef}`
        : null;
    const imageAsset = imageUri ? await resolveAsset(imageUri, fns) : null;
    const url =
      imageAsset?.url ||
      (Array.isArray(imageAsset?.urls) ? imageAsset.urls[0] : "") ||
      "";
    if (url) {
      return { url, alt: imageAsset.name || "", width: null, height: null };
    }
  }

  const thumbnail = page.thumbnail;
  return thumbnail
    ? {
        url: thumbnail.url || "",
        alt: thumbnail.alt || thumbnail.title || "",
        width: thumbnail.width || null,
        height: thumbnail.height || null,
      }
    : null;
}

/**
 * Per the real Matrix asset schema, `metadata` is a key-value map where
 * every value is an array of strings (Matrix metadata fields are
 * multi-value by design), e.g. {"content-cardIcon": ["briefcase"]} -- not a
 * flat {icon: "briefcase"} shape. This reads the first value for a given
 * key. Key names below are confirmed against the real "Content - 04 Card
 * support" metadata schema (content-cardTitle/-cardDescription/-cardIcon/
 * -cardButtonText); `Date`/`Category` have no confirmed match in that
 * schema and remain a best-effort guess -- see card.spec.md assumption 1.
 */
function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? value[0] || "" : "";
}

/**
 * Maps one resolved Squiz asset onto card content. `url` is a confirmed
 * generic MatrixAssetSchema field; title/description/actionText prefer the
 * real site's dedicated card-override metadata fields, falling back to the
 * asset's own name/a fixed constant when blank; image resolves the
 * `content-cardImagePhoto` Related Asset field (see resolveCardImage),
 * falling back to the generic `thumbnail` attribute. `tagLabel`/`date` have
 * no confirmed metadata field -- see card.spec.md assumption 1. Any field
 * absent from the resolved asset is simply omitted from the card (never
 * throws).
 */
async function toCard(page, domain, fns) {
  if (!page) return null;
  const metadata = page.metadata || {};

  return {
    title: firstMetadataValue(metadata, "content-cardTitle") || page.name || "",
    description: firstMetadataValue(metadata, "content-cardDescription"),
    image: await resolveCardImage(page, domain, fns),
    date: firstMetadataValue(metadata, "Date"),
    tagLabel: firstMetadataValue(metadata, "Category"),
    href: page.url || "",
    actionText:
      firstMetadataValue(metadata, "content-cardButtonText") || ACTION_TEXT,
  };
}

/**
 * Resolves the `assets` field into a flat list of card data (Card mode:
 * "Page") -- each entry is resolved via resolveUri and contributes one
 * card. Best-effort: any source that fails to resolve contributes nothing
 * rather than throwing.
 */
async function resolveCards(assets, fns) {
  const sources = Array.isArray(assets) ? assets : [];
  const resolvedLists = await Promise.all(
    sources.map(async (uri) => {
      const resolved = await resolveAsset(uri, fns);
      const domain = parseAssetUriDomain(uri);
      const card = await toCard(resolved, domain, fns);
      return card ? [card] : [];
    }),
  );

  return resolvedLists.flat();
}

function renderCard(card, visibility) {
  const resolvedImage = visibility.showImage ? card.image : null;
  const tagLabel = visibility.showTags ? card.tagLabel : "";
  const date = visibility.showDate ? card.date : "";
  const titleId = `card-title-${Math.random().toString(36).slice(2, 9)}`;

  const imageHtml = resolvedImage
    ? `
    <div class="card__image">
      <img src="${escURL(resolvedImage.url)}" alt="${escHTML(resolvedImage.alt)}"${resolvedImage.width ? ` width="${resolvedImage.width}"` : ""}${resolvedImage.height ? ` height="${resolvedImage.height}"` : ""} />
    </div>`
    : "";

  const hasHeader = Boolean(tagLabel || date);
  const headerHtml = hasHeader
    ? `
      <div class="card__header">
        ${tagLabel ? `<span class="card__tag">${escHTML(tagLabel)}</span>` : ""}
        ${date ? `<span class="card__date">${escHTML(date)}</span>` : ""}
      </div>`
    : "";

  const descriptionHtml = visibility.showDescription && card.description
    ? `<p class="card__description">${escHTML(card.description)}</p>`
    : "";

  const footerHtml = visibility.showActionLink && card.actionText
    ? `
      <div class="card__footer">
        <span class="card__action">${escHTML(card.actionText)} <span class="card__action-icon">${ARROW_RIGHT_SVG}</span></span>
      </div>`
    : "";

  const innerHtml = `${imageHtml}
    <div class="card__content">${headerHtml}
      <div class="card__body">
        <h3 class="card__title" id="${titleId}">${escHTML(card.title)}</h3>
        ${descriptionHtml}
      </div>${footerHtml}
    </div>`;

  return card.href
    ? /*html*/ `<a class="card" href="${escURL(card.href)}" aria-labelledby="${titleId}">${innerHtml}</a>`
    : /*html*/ `<article class="card">${innerHtml}</article>`;
}

/**
 * Resolves the `assets` field into render-ready { icon, label, href } items
 * (Card mode: "Mini Cards") -- icon comes from the asset's
 * 'content-cardIcon' metadata field (confirmed against the real "Content -
 * 04 Card support" metadata schema, default value "briefcase" matching this
 * project's Font Awesome classic/thin convention), label from its name,
 * href from its url.
 */
async function resolveMiniCards(assets, fns) {
  const sources = Array.isArray(assets) ? assets : [];
  const resolved = await Promise.all(
    sources.map(async (uri) => {
      const asset = await resolveAsset(uri, fns);
      if (!asset) return null;
      return {
        icon: firstMetadataValue(asset.metadata || {}, "content-cardIcon"),
        label: asset.name || "",
        href: asset.url || "",
      };
    }),
  );

  return resolved.filter(Boolean);
}

/**
 * Maps one resolved asset onto a { icon, title, description, href } item
 * (Card mode: "Homepage Cards") -- icon and title/description read from
 * the same metadata fields as the other two modes (content-cardIcon,
 * content-cardTitle falling back to name, content-cardDescription), no new
 * metadata contract.
 */
function toHomepageCard(asset) {
  if (!asset) return null;
  const metadata = asset.metadata || {};
  return {
    icon: firstMetadataValue(metadata, "content-cardIcon"),
    title:
      firstMetadataValue(metadata, "content-cardTitle") || asset.name || "",
    description: firstMetadataValue(metadata, "content-cardDescription"),
    href: asset.url || "",
  };
}

/**
 * Resolves the `assets` field into render-ready Homepage Card items --
 * same resolution mechanism as resolveCards/resolveMiniCards, different
 * mapping function only.
 */
async function resolveHomepageCards(assets, fns) {
  const sources = Array.isArray(assets) ? assets : [];
  const resolvedLists = await Promise.all(
    sources.map(async (uri) => {
      const asset = await resolveAsset(uri, fns);
      const card = toHomepageCard(asset);
      return card ? [card] : [];
    }),
  );

  return resolvedLists.flat();
}

function renderHomepageCard(card) {
  const titleId = `homepage-card-title-${Math.random().toString(36).slice(2, 9)}`;
  const iconHtml = card.icon
    ? `<i class="fal fa-lg fa-${escHTML(card.icon)}" aria-hidden="true"></i>`
    : "";
  const descriptionHtml = card.description
    ? `<p class="homepage-card__description">${escHTML(card.description)}</p>`
    : "";

  const innerHtml = `
    <h3 class="homepage-card__title" id="${titleId}">${iconHtml}${escHTML(card.title)}</h3>
    <div class="homepage-card__divider" aria-hidden="true"></div>
    ${descriptionHtml}`;

  return card.href
    ? /*html*/ `<a class="homepage-card" href="${escURL(card.href)}" aria-labelledby="${titleId}">${innerHtml}</a>`
    : /*html*/ `<div class="homepage-card">${innerHtml}</div>`;
}

/**
 * Maps one resolved asset onto a { icon, title, description, href } item
 * (Card mode: "Display Cards Icons") -- same three metadata fields as
 * Homepage Cards (content-cardIcon/-cardTitle/-cardDescription), no new
 * metadata contract; the only difference from Homepage Cards is the
 * bordered-box visual treatment (reuses `.card`/`.card__body`, see
 * renderDisplayCardIcon()) instead of Homepage Cards' plain-link style.
 */
function toDisplayCardIcon(asset) {
  if (!asset) return null;
  const metadata = asset.metadata || {};
  return {
    icon: firstMetadataValue(metadata, "content-cardIcon"),
    title:
      firstMetadataValue(metadata, "content-cardTitle") || asset.name || "",
    description: firstMetadataValue(metadata, "content-cardDescription"),
    href: asset.url || "",
  };
}

/**
 * Resolves the `assets` field into render-ready Display Cards Icons items --
 * same resolution mechanism as resolveCards/resolveHomepageCards, different
 * mapping function only.
 */
async function resolveDisplayCardIcons(assets, fns) {
  const sources = Array.isArray(assets) ? assets : [];
  const resolvedLists = await Promise.all(
    sources.map(async (uri) => {
      const asset = await resolveAsset(uri, fns);
      const card = toDisplayCardIcon(asset);
      return card ? [card] : [];
    }),
  );

  return resolvedLists.flat();
}

/**
 * Reuses Display Cards' own `.card`/`.card__content`/`.card__body` bordered
 * box (border, background, hover/focus) verbatim -- only the top block
 * differs: a `.card__icon` (Font Awesome, matching Homepage/Mini Cards'
 * icon field) in place of `.card__image`, and no header (tag/date) or
 * footer (action link) at all, matching the reference screenshot exactly.
 * `visibilityOptions` intentionally has no effect here (see card.spec.md
 * assumption 19) -- not requested, and this mode has no image/tag/date/
 * action-link elements to toggle in the first place; the description alone
 * has no dedicated toggle since none was requested either.
 */
function renderDisplayCardIcon(card) {
  const titleId = `card-icon-title-${Math.random().toString(36).slice(2, 9)}`;
  const iconHtml = card.icon
    ? `<div class="card__icon"><i class="fa-thin fa-${escHTML(card.icon)}" aria-hidden="true"></i></div>`
    : "";
  const descriptionHtml = card.description
    ? `<p class="card__description">${escHTML(card.description)}</p>`
    : "";

  const innerHtml = `${iconHtml}
    <div class="card__content">
      <div class="card__body">
        <h3 class="card__title" id="${titleId}">${escHTML(card.title)}</h3>
        ${descriptionHtml}
      </div>
    </div>`;

  return card.href
    ? /*html*/ `<a class="card" href="${escURL(card.href)}" aria-labelledby="${titleId}">${innerHtml}</a>`
    : /*html*/ `<article class="card">${innerHtml}</article>`;
}

function renderMiniCard(item) {
  const { icon = "", label = "", href = "" } = item || {};
  const iconHtml = icon ? `<i class="fa-thin fa-${escHTML(icon)}"></i>` : "";

  const innerHtml = `
    <span class="mini-card__icon" aria-hidden="true">${iconHtml}</span>
    <span class="mini-card__label">${escHTML(label)}</span>`;

  return href
    ? /*html*/ `<a class="mini-card" href="${escURL(href)}">${innerHtml}</a>`
    : /*html*/ `<div class="mini-card">${innerHtml}</div>`;
}

/**
 * Maps one resolved asset onto a News Card. title/description/image reuse
 * the exact same fields as Display Cards mode (content-cardTitle falling
 * back to name, content-cardDescription, content-cardImagePhoto via
 * resolveCardImage). `date` reads `news-datePublished` -- a distinct
 * metadata field from Display Cards' unconfirmed `Date`, confirmed via
 * user-provided macro syntax (`asset_metadata_news-datePublished`). See
 * card.spec.md assumption 7.
 */
async function toNewsCard(asset, domain, fns) {
  if (!asset) return null;
  const metadata = asset.metadata || {};

  return {
    title:
      firstMetadataValue(metadata, "content-cardTitle") || asset.name || "",
    description: firstMetadataValue(metadata, "content-cardDescription"),
    image: await resolveCardImage(asset, domain, fns),
    date: firstMetadataValue(metadata, "news-datePublished"),
    href: asset.url || "",
  };
}

/**
 * Parses a "26 Jun 2026"-style date string (same display convention as
 * Display Cards' Date field) into a sortable timestamp. Missing/unparsable
 * values sort last (-Infinity) rather than throwing or crashing the sort.
 */
function parseNewsDate(value) {
  const ms = Date.parse(value || "");
  return Number.isNaN(ms) ? -Infinity : ms;
}

/**
 * Resolves the `assets` field into News Cards, sorted newest-first by
 * `news-datePublished` -- explicit user requirement, since editors may
 * select assets in any order -- then capped to the 3 most recent
 * (NEWS_CARDS_MAX_ITEMS).
 */
async function resolveNewsCards(assets, fns) {
  const sources = Array.isArray(assets) ? assets : [];
  const resolvedLists = await Promise.all(
    sources.map(async (uri) => {
      const resolved = await resolveAsset(uri, fns);
      const domain = parseAssetUriDomain(uri);
      const card = await toNewsCard(resolved, domain, fns);
      return card ? [card] : [];
    }),
  );

  return resolvedLists
    .flat()
    .sort((a, b) => parseNewsDate(b.date) - parseNewsDate(a.date))
    .slice(0, NEWS_CARDS_MAX_ITEMS);
}

function renderNewsCard(card, visibility) {
  const resolvedImage = visibility.showImage ? card.image : null;
  const date = visibility.showDate ? card.date : "";
  const titleId = `news-card-title-${Math.random().toString(36).slice(2, 9)}`;

  const imageHtml = resolvedImage
    ? `
    <div class="card__image">
      <img src="${escURL(resolvedImage.url)}" alt="${escHTML(resolvedImage.alt)}"${resolvedImage.width ? ` width="${resolvedImage.width}"` : ""}${resolvedImage.height ? ` height="${resolvedImage.height}"` : ""} />
    </div>`
    : "";

  const descriptionHtml = visibility.showDescription && card.description
    ? `<p class="card__description">${escHTML(card.description)}</p>`
    : "";

  const innerHtml = `${imageHtml}
    <div class="card__content">
      <div class="news-card__header">
        ${visibility.showTags ? `<span class="card__tag">${escHTML(NEWS_TAG_LABEL)}</span>` : ""}
        ${date ? `<span class="news-card__date">${escHTML(date)}</span>` : ""}
      </div>
      <div class="news-card__divider" aria-hidden="true"></div>
      <div class="card__body">
        <h3 class="card__title" id="${titleId}">${escHTML(card.title)}</h3>
        ${descriptionHtml}
      </div>
    </div>`;

  return card.href
    ? /*html*/ `<a class="card" href="${escURL(card.href)}" aria-labelledby="${titleId}">${innerHtml}</a>`
    : /*html*/ `<article class="card">${innerHtml}</article>`;
}

/**
 * Optional section wrapper (heading + "View all" button) around a mode's
 * `.card-grid`, available to every card mode via `layoutOptions` -- was
 * News Cards-only fixed text until this revision. See card.spec.md
 * assumption 20/21. Heading and button are two independent tick options
 * (`showSectionHeading`/`showViewAllButton`) -- either can be on without
 * the other. A blank `sectionHeading` still omits the `<h2>` even when its
 * tick is on, and an unresolved `viewAllButton` (SquizLink with no url
 * configured) still omits the `<a>`; the header row itself is omitted
 * entirely when both end up empty.
 */
function renderCardSection(itemsHtml, attrs, showHeading, sectionHeading, showButton, link) {
  const heading = showHeading ? String(sectionHeading ?? "").trim() : "";
  const headingHtml = heading
    ? `<h2 class="card-section__title">${escHTML(heading)}</h2>`
    : "";
  const buttonHtml = showButton && link
    ? `<a class="button card-section__view-all" href="${escURL(link.url)}"${targetAttrs(link.target)}>${escHTML(link.text)}</a>`
    : "";
  const headerHtml = headingHtml || buttonHtml
    ? `<div class="card-section__header">${headingHtml}${buttonHtml}</div>`
    : "";

  return /*html*/ `
<div ${attrs} class="card-section">
  ${headerHtml}
  <div class="card-grid">
    ${itemsHtml}
  </div>
</div>
`;
}

/**
 * Combines individually-picked assets with every child of the picked parent
 * (`parentAsset`), de-duplicated by uri in case the same asset is reachable
 * both ways.
 */
async function resolveCombinedAssets(assets, parentAsset, contentApiUrl) {
  const parentChildUris = await resolveParentChildUris(
    parentAsset,
    contentApiUrl,
  );
  const sources = Array.isArray(assets) ? assets : [];

  const seen = new Set();
  return [...sources, ...parentChildUris].filter((uri) => {
    if (seen.has(uri)) return false;
    seen.add(uri);
    return true;
  });
}

export default {
  async main(input = {}, info = {}) {
    const {
      cardMode = "Display Cards",
      assets = [],
      parentAsset = "",
      visibilityOptions = {},
      layoutOptions = {},
    } = input;
    const {
      showImage = true,
      showTags = true,
      showDate = true,
      showDescription = true,
      showActionLink = true,
    } = visibilityOptions;
    const {
      showSectionHeading,
      sectionHeading = "What we are doing",
      showViewAllButton,
      viewAllButton,
    } = layoutOptions;
    const shouldShowSectionHeading =
      showSectionHeading !== undefined
        ? Boolean(showSectionHeading)
        : cardMode === "News Cards";
    const shouldShowViewAllButton =
      showViewAllButton !== undefined
        ? Boolean(showViewAllButton)
        : cardMode === "News Cards";
    const resolvedViewAllLink = resolveLink(viewAllButton);

    const combinedAssets = await resolveCombinedAssets(
      assets,
      parentAsset,
      info.env?.CONTENT_API_URL,
    );
    const attrs = componentAttrs("card", input);
    const visibility = { showImage, showTags, showDate, showDescription, showActionLink };

    let itemsHtml;
    if (cardMode === "Display Cards Icons") {
      const displayCardIcons = await resolveDisplayCardIcons(
        combinedAssets,
        info.fns,
      );
      itemsHtml = displayCardIcons.map(renderDisplayCardIcon).join("");
    } else if (cardMode === "Mini Cards") {
      const items = await resolveMiniCards(combinedAssets, info.fns);
      itemsHtml = items.map(renderMiniCard).join("");
    } else if (cardMode === "Homepage Cards") {
      const homepageCards = await resolveHomepageCards(
        combinedAssets,
        info.fns,
      );
      itemsHtml = homepageCards.map(renderHomepageCard).join("");
    } else if (cardMode === "News Cards") {
      const newsCards = await resolveNewsCards(combinedAssets, info.fns);
      itemsHtml = newsCards.map((card) => renderNewsCard(card, visibility)).join("");
    } else {
      const cards = await resolveCards(combinedAssets, info.fns);
      itemsHtml = cards.map((card) => renderCard(card, visibility)).join("");
    }

    if (!shouldShowSectionHeading && !shouldShowViewAllButton) {
      return /*html*/ `
<div ${attrs} class="card-grid">
  ${itemsHtml}
</div>
`;
    }

    return renderCardSection(
      itemsHtml,
      attrs,
      shouldShowSectionHeading,
      sectionHeading,
      shouldShowViewAllButton,
      resolvedViewAllLink,
    );
  },
};
